/* Generated by scripts/brand.py — the Runfold mark in the active skin's
   colours: three discs through each other's centres (the reading levels),
   stacked like sheets lit from behind; their common core, a Reuleaux
   triangle pointing right, is the play (Run) and the brightest part. */

const MARK = `<defs><clipPath id="rf-hdr0"><circle cx="63.279" cy="50" r="30.667"/></clipPath><clipPath id="rf-hdr1"><circle cx="36.721" cy="65.333" r="30.667"/></clipPath><clipPath id="rf-hdr2"><circle cx="36.721" cy="34.667" r="30.667"/></clipPath></defs><circle cx="63.279" cy="50" r="30.667" style="fill:var(--rf-deep)"/><circle cx="36.721" cy="65.333" r="30.667" style="fill:var(--rf-guided)"/><circle cx="36.721" cy="34.667" r="30.667" style="fill:var(--rf-quick)"/><g clip-path="url(#rf-hdr0)"><circle cx="36.721" cy="65.333" r="30.667" style="fill:color-mix(in oklab, var(--rf-guided) 84%, white)"/></g><g clip-path="url(#rf-hdr1)"><circle cx="36.721" cy="34.667" r="30.667" style="fill:color-mix(in oklab, var(--rf-quick) 80%, white)"/></g><g clip-path="url(#rf-hdr2)"><circle cx="63.279" cy="50" r="30.667" style="fill:color-mix(in oklab, var(--rf-quick) 55%, var(--accent))"/></g><g clip-path="url(#rf-hdr0)"><g clip-path="url(#rf-hdr1)"><circle cx="36.721" cy="34.667" r="30.667" style="fill:var(--rf-core)"/></g></g>`;

export function RunfoldMark({ className }: { className?: string }) {
  return <svg viewBox="0 0 100 100" className={"rf-mark " + (className ?? "")} aria-hidden dangerouslySetInnerHTML={{ __html: MARK }} />;
}
